SZGame2D.onStart(function __szProjectRun() {
  const __szProjectRunContext = window.__SZProjectLifecycle.begin(() => SZGame2D.restart());
  // Ao iniciar
  SZGame2D.setupStage(640, 480, "#d8f3f3");
  SZGame2D.enableClassicControls("always");
  let direita = 1;
  const concha = SZGame2D.createSprite({ x: 270, y: 165, w: 100, h: 100, image: "concha" });
  // Quando acontecer
  SZGame2D.onKey("Enter", () => {

  }, "recife-quadro-1_events_0");
  SZGame2D.onKey("Space", () => {

  }, "recife-quadro-1_events_1");
  // Enquanto estiver rodando
  // O jogo roda 60 passos por segundo: cada volta desenha um "quadro" do filme.
  SZGame2D.gameLoop(function update() {
    if (direita === 1) {
      if (SZGame2D.spriteX(concha) < 500) {
        concha.vx = 1; concha.vy = 0;
        SZGame2D.applyVelocity(concha);
      }
    } else {
      if (SZGame2D.spriteX(concha) > 40) {
        concha.vx = -1; concha.vy = 0;
        SZGame2D.applyVelocity(concha);
      }
    }
    SZGame2D.clear();
    SZGame2D.drawLabel(ctx, "A corrente muda", 24, 35, "#123d55", 19, "left");
    SZGame2D.drawLabel(ctx, "Espaço muda o sentido da corrente.", 24, 72, "#123d55", 19, "left");
    SZGame2D.drawLabel(ctx, "1 vai para a direita. 0 vai para a esquerda.", 24, 103, "#123d55", 19, "left");
    SZGame2D.drawSprite(ctx, concha);
    SZGame2D.drawLabel(ctx, "Sentido da corrente:", 24, 355, "#123d55", 19, "left");
    SZGame2D.drawLabel(ctx, direita, 290, 355, "#123d55", 19, "left");
    SZGame2D.drawLabel(ctx, "Enter: nova rodada depois de completar o extra.", 24, 449, "#123d55", 19, "left");
  }, "recife-quadro-1_loops_0");
}, "__sz-project");

